import json as _json
from httpbin.core import app

client = app.test_client()

def test_put_with_json_body_returns_200_and_all_keys():
    payload = {"key": "value", "number": 42}
    r = client.put(
        '/put',
        data=_json.dumps(payload),
        content_type='application/json'
    )
    assert r.status_code == 200
    body = _json.loads(r.data)
    for key in ('url', 'args', 'headers', 'form', 'data', 'files', 'json', 'origin'):
        assert key in body, f"Missing key: {key}"
    assert body['json'] == {"key": "value", "number": 42}
    assert body['form'] == {}
    assert body['args'] == {}
    assert body['data'] == _json.dumps(payload)

test_put_with_json_body_returns_200_and_all_keys()
